const body = $json.body || {};
const msgData = body?.data;
if (!msgData) return [];
if (msgData?.key?.fromMe) return [];
const jid1 = msgData?.key?.remoteJid || '';
const jid2 = msgData?.key?.remoteJidAlt || '';
let telefone = jid1.includes('@s.whatsapp.net') ? jid1 : (jid2.includes('@s.whatsapp.net') ? jid2 : '');
telefone = String(telefone).replace('@s.whatsapp.net', '').replace(/\D/g, '');
const mensagem = String(msgData?.message?.extendedTextMessage?.text || msgData?.message?.conversation || '').trim();
const nome = String(msgData?.pushName || 'Cliente').trim();
const lower = mensagem.toLowerCase();
let intent = 'ajuda';
if (/( servi[cç]os? | pre[cç]o | valores? )/.test(lower)) intent = 'listar_servicos';
else if (/( barbeiros? | profissionais? )/.test(lower)) intent = 'listar_profissionais';
else if (/( meus agendamentos | minhas consultas | meus horarios | meus horários )/.test(lower)) intent = 'consultar_meus_agendamentos';
else if (/( cancelar )/.test(lower)) intent = 'cancelar_agendamento';
else if (/( reagendar | remarcar )/.test(lower)) intent = 'reagendar_agendamento';
else if (/( agendar | reservar | marcar )/.test(lower)) intent = 'criar_agendamento';
const idMatch = mensagem.match(/\b(\d{1,9})\b/);
const isoMatch = mensagem.match(/\b(20\d{2}-\d{2}-\d{2})(?:[ T](\d{2}:\d{2}))?\b/);
const slashMatch = mensagem.match(/\b(\d{2})[\/\-](\d{2})[\/\-](20\d{2})(?:\s+(\d{1,2}:\d{2}))?\b/);
const timeOnlyMatch = mensagem.match(/\b(\d{1,2}:\d{2})\b/);
let dataIso = null;
if (isoMatch) dataIso = `${isoMatch[1]}T${isoMatch[2] || '09:00'}:00-03:00`;
else if (slashMatch) dataIso = `${slashMatch[3]}-${slashMatch[2]}-${slashMatch[1]}T${(slashMatch[4] || '09:00').padStart(5, '0')}:00-03:00`;
else if (timeOnlyMatch) dataIso = `2026-08-06T${timeOnlyMatch[1].padStart(5, '0')}:00-03:00`;
const staticData = $getWorkflowStaticData('global');
const state = staticData[`wpp:${telefone}`] || { stage: 0 };
return [{ json: { Telefone: telefone, Mensagem: mensagem, NomeWpp: nome, intent, agendamentoId: idMatch ? Number(idMatch[1]) : null, dataIso, rawBody: body, stateStage: state.stage || 0, statePayload: state } }];

const catalogo = $json;
const servicos = Array.isArray(catalogo.servicos) ? catalogo.servicos : [];
const texto = servicos.length ? ['Serviços disponíveis:', '', ...servicos.map((s) => `- ${s.id}: ${s.nome}${s.preco != null ? ' - R$ ' + s.preco : ''}`)].join('\n') : 'Não encontrei serviços cadastrados no momento.';
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const catalogo = $json;
const tenant = catalogo.tenant?.nome || 'a barbearia';
const texto = [
  `Olá! Eu sou o assistente da ${tenant}.`,
  '',
  'Posso te ajudar com:',
  '- agendar',
  '- reagendar',
  '- cancelar',
  '- ver serviços',
  '- ver barbeiros',
  '',
  'Se quiser começar, me diga: quero agendar.'
].join('\n');
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const catalogo = $json;
const profissionais = Array.isArray(catalogo.profissionais) ? catalogo.profissionais : [];
const texto = profissionais.length ? ['Profissionais disponíveis:', '', ...profissionais.map((p) => `- ${p.id}: ${p.nome}`)].join('\n') : 'Não encontrei profissionais cadastrados no momento.';
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const lista = Array.isArray($json) ? $json : ($json.data || []);
const texto = lista.length ? ['Seus agendamentos:', '', ...lista.map((a) => `- #${a.id} | ${a.data || a.dataHora || a.inicio || 'sem data'} | ${a.status || 'ativo'}`)].join('\n') : 'Nenhum agendamento encontrado para o seu telefone.';
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const base = $node['Variaveis do sistema'].json;
const current = $json;
const telefone = String(base.Telefone || '').replace(/\D/g, '');
const message = String(base.Mensagem || '');
const lower = message.toLowerCase();
const state = base.statePayload || { stage: 0 };
const stage = Number(base.stateStage || state.stage || 0);
const servicos = Array.isArray(current.servicos) ? current.servicos : [];
const profissionais = Array.isArray(current.profissionais) ? current.profissionais : [];
const store = $getWorkflowStaticData('global');
const parseId = (text) => { const m = String(text || '').match(/\b(\d{1,9})\b/); return m ? Number(m[1]) : null; };
const normalize = (s) => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const findByName = (items) => items.find((i) => normalize(message).includes(normalize(i.nome)));
const parseDate = (text) => {
  const iso = String(text || '').match(/\b(20\d{2}-\d{2}-\d{2})(?:[ T](\d{2}:\d{2}))?\b/);
  if (iso) return `${iso[1]}T${iso[2] || '09:00'}:00-03:00`;
  const slash = String(text || '').match(/\b(\d{2})[\/\-](\d{2})[\/\-](20\d{2})(?:\s+(\d{1,2}:\d{2}))?\b/);
  if (slash) return `${slash[3]}-${slash[2]}-${slash[1]}T${(slash[4] || '09:00').padStart(5, '0')}:00-03:00`;
  return null;
};
const clearState = () => { delete store[`wpp:${telefone}`]; };
const listServicos = servicos.slice(0, 8).map((s) => `${s.id}-${s.nome}`).join(', ');
const listProfissionais = profissionais.slice(0, 8).map((p) => `${p.id}-${p.nome}`).join(', ');
if (/\b(cancelar|parar|sair|desistir|cancelando)\b/.test(lower)) {
  clearState();
  return [{ json: { ...base, mensagemEnvio: 'Beleza, cancelei o fluxo de agendamento. Se quiser, me chame de novo.' } }];
}
if (stage === 0) {
  store[`wpp:${telefone}`] = { stage: 1 };
  return [{ json: { ...base, mensagemEnvio: ['Vamos agendar passo a passo.', '', 'Me diga primeiro qual serviço você quer.', 'Serviços disponíveis: ' + listServicos].join('\n') } }];
}
if (stage === 1) {
  const servico = servicos.find((s) => s.id === parseId(message)) || findByName(servicos);
  if (!servico) return [{ json: { ...base, mensagemEnvio: `Me diga qual serviço você quer agendar. Pode mandar o número ou o nome.\nServiços disponíveis: ${listServicos}` } }];
  store[`wpp:${telefone}`] = { stage: 2, servicoId: servico.id, servicoNome: servico.nome };
  return [{ json: { ...base, mensagemEnvio: `Perfeito. Agora me diga o profissional desejado. Você pode mandar o número ou o nome.\nProfissionais disponíveis: ${listProfissionais}` } }];
}
if (stage === 2) {
  const profissional = profissionais.find((p) => p.id === parseId(message)) || findByName(profissionais);
  if (!profissional) return [{ json: { ...base, mensagemEnvio: `Agora me diga qual profissional você prefere. Pode mandar o número ou o nome.\nProfissionais disponíveis: ${listProfissionais}` } }];
  store[`wpp:${telefone}`] = { stage: 3, servicoId: state.servicoId, servicoNome: state.servicoNome, profissionalId: profissional.id, profissionalNome: profissional.nome };
  return [{ json: { ...base, mensagemEnvio: 'Ótimo. Agora me passe a data e hora. Aceito 2026-08-10 14:30 ou 10/08/2026 14:30.' } }];
}
if (stage === 3) {
  const dataIso = base.dataIso || parseDate(message);
  if (!dataIso) return [{ json: { ...base, mensagemEnvio: 'Só falta a data e hora. Envie no formato 2026-08-10 14:30 ou 10/08/2026 14:30.' } }];
  const dt = new Date(dataIso);
  if (Number.isNaN(dt.getTime()) || dt.getTime() < Date.now()) {
    return [{ json: { ...base, mensagemEnvio: 'Essa data parece inválida ou já passou. Envie uma data futura, por exemplo 2026-08-10 14:30.' } }];
  }
  store[`wpp:${telefone}`] = { stage: 4, servicoId: state.servicoId, servicoNome: state.servicoNome, profissionalId: state.profissionalId, profissionalNome: state.profissionalNome, dataIso };
  return [{ json: { ...base, servicoId: state.servicoId, profissionalId: state.profissionalId, dataIso, podeCriar: true } }];
}
if (stage >= 4) return [{ json: { ...base, servicoId: state.servicoId, profissionalId: state.profissionalId, dataIso: state.dataIso, podeCriar: true } }];
return [{ json: { ...base, mensagemEnvio: 'Me envie a solicitação de agendamento novamente.' } }];

const ag = $json;
const id = ag.id || ag.agendamento?.id || 'novo';
const texto = `Agendamento confirmado com sucesso. ID: ${id}.`;
const store = $getWorkflowStaticData('global');
const telefone = String($node['Variaveis do sistema'].json.Telefone || '').replace(/\D/g, '');
delete store[`wpp:${telefone}`];
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const r = $json;
const texto = `Agendamento ${r.id || $node['Variaveis do sistema'].json.agendamentoId || ''} cancelado com sucesso.`;
const store = $getWorkflowStaticData('global');
const telefone = String($node['Variaveis do sistema'].json.Telefone || '').replace(/\D/g, '');
delete store[`wpp:${telefone}`];
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];

const r = $json;
const texto = `Agendamento ${r.id || $node['Variaveis do sistema'].json.agendamentoId || ''} reagendado com sucesso para ${$node['Variaveis do sistema'].json.dataIso || 'a nova data informada'}.`;
const store = $getWorkflowStaticData('global');
const telefone = String($node['Variaveis do sistema'].json.Telefone || '').replace(/\D/g, '');
delete store[`wpp:${telefone}`];
return [{ json: { ...$node['Variaveis do sistema'].json, mensagemEnvio: texto } }];
